describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const policies: DiscountPolicy[] = [
        new PercentageDiscountPolicy(10), // 10% of 1000 = 100
        new FixedAmountDiscountPolicy(200), // fixed 200
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child discounts to 0 before summing", () => {
      const negativePolicy: DiscountPolicy = {
        computeDiscountCents: () => -100,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(50)],
        "sum",
      );
      // -100 clamped to 0, plus 50 = 50
      expect(composite.computeDiscountCents(1000)).toBe(50);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially against remaining subtotal", () => {
      const policies: DiscountPolicy[] = [
        new PercentageDiscountPolicy(10), // 10% of 1000 = 100 → remaining 900
        new PercentageDiscountPolicy(10), // 10% of 900 = 90 → remaining 810
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("stops accumulating when remaining is exhausted", () => {
      const policies: DiscountPolicy[] = [
        new FixedAmountDiscountPolicy(800), // 800 off 1000 → remaining 200
        new FixedAmountDiscountPolicy(500), // wants 500, but only 200 remains
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("ordering matters — larger discount first yields different result", () => {
      const policiesA: DiscountPolicy[] = [
        new PercentageDiscountPolicy(50), // 500 off 1000 → remaining 500
        new FixedAmountDiscountPolicy(200), // 200 off 500 → remaining 300
      ];
      const policiesB: DiscountPolicy[] = [
        new FixedAmountDiscountPolicy(200), // 200 off 1000 → remaining 800
        new PercentageDiscountPolicy(50), // 50% of 800 = 400
      ];
      const compositeA = new CompositeDiscountPolicy(policiesA, "chain");
      const compositeB = new CompositeDiscountPolicy(policiesB, "chain");
      expect(compositeA.computeDiscountCents(1000)).toBe(700);
      expect(compositeB.computeDiscountCents(1000)).toBe(600);
    });

    it("clamps negative child discount to 0", () => {
      const negativePolicy: DiscountPolicy = {
        computeDiscountCents: () => -50,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      // -50 clamped to 0, then 100 off 1000 = 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });
  });
});
"}

