describe("Cart – totals (pricing pipeline)", () => {
  it("computes subtotal as sum of unitPrice × quantity", () => {
    const cart = new Cart();
    cart.add(product({ id: "a", unitPriceCents: 500 }), 2);
    cart.add(product({ id: "b", unitPriceCents: 300 }), 3);
    const totals = cart.totals();
    // 500*2 + 300*3 = 1900
    expect(totals.subtotalCents).toBe(1900);
  });

  it("applies discount, then tax on discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({ discountPolicy, taxCalculator });
    cart.add(product({ unitPriceCents: 1000 }), 1);
    const totals = cart.totals();

    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(200);
    // Tax computed on discounted subtotal (1000 - 200 = 800)
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US");
    expect(totals.taxCents).toBe(80);
  });

  it("shipping receives discounted subtotal and lines", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(product({ unitPriceCents: 500 }), 2);
    const totals = cart.totals();

    // Discounted subtotal = 1000 - 100 = 900
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      900,
    );
    expect(totals.shippingCents).toBe(599);
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 200,
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: () => 80,
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => 500,
    };
    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
    cart.add(product({ unitPriceCents: 1000 }), 1);
    const totals = cart.totals();

    expect(totals.totalCents).toBe(800 + 80 + 500); // 1380
  });

  it("clamps discount to [0, subtotal] — negative discount becomes 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => -100,
    };
    const cart = new Cart({ discountPolicy });
    cart.add(product({ unitPriceCents: 500 }), 1);
