      computeDiscountCents: () => 200,
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => 500,
    };
    const cart = new Cart({ discountPolicy, shippingCalculator, region: "US-CA" });
    cart.add(product({ unitPriceCents: 1000 }), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });

    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    // subtotal = 1000, discount = 200, discountedSubtotal = 800
    // tax = 10% of 800 = 80
    // shipping = 500
    // total = 800 + 80 + 500 = 1380
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(80);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(1380);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(product(), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "rate service down",
    );
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const cart = new Cart({ region: "GB" });
    cart.add(product({ id: "item", unitPriceCents: 100 }), 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(600),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.2),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // Price refreshed to 600 → subtotal = 600 * 2 = 1200
    expect(result.totals.subtotalCents).toBe(1200);
    // Default no-discount → discountCents = 0
    expect(result.totals.discountCents).toBe(0);
    // 20% tax on 1200 = 240
    expect(result.totals.taxCents).toBe(240);
    // Free shipping by default
    expect(result.totals.shippingCents).toBe(0);
    expect(result.totals.totalCents).toBe(1440);

    expect(inventoryChecker.check).toHaveBeenCalledWith("item", 2);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("GB");
  });

  it("inventory check fails on first denied item", async () => {
    const cart = new Cart();
    cart.add(product({ id: "ok" }), 1);
    cart.add(product({ id: "nope" }), 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false }),
    };

    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
  });

  it("priceFetcher error propagates and aborts checkout", async () => {
    const cart = new Cart();
    cart.add(product(), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price api down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price api down",
    );
  });
});
