toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
  type WeightBracket,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const line = (
  id: string,
  weightGrams: number,
  quantity = 1,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

const noWeightLine = (id: string, quantity = 1): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000 },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([line("a", 500)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(9.99)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([line("a", 100)], 1000)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal meets free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([line("a", 100)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([line("a", 100)], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal is just below threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([line("a", 100)], 4999)).toBe(599);
    });

    it("returns flat fee when no threshold is configured", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([line("a", 100)], 100000)).toBe(799);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  const brackets: WeightBracket[] = [
    { upToGrams: 500, costCents: 300 },
    { upToGrams: 1000, costCents: 500 },
    { upToGrams: 5000, costCents: 1000 },
  ];

  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(brackets);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when all items have zero/undefined weight", () => {
      expect(
        calc.computeShippingCents([noWeightLine("a", 3)], 1000),
      ).toBe(0);
    });

    it("selects first bracket (weight ≤ 500g)", () => {
      expect(calc.computeShippingCents([line("a", 250, 2)], 1000)).toBe(300);
    });

    it("selects bracket at exact boundary (500g)", () => {
      expect(calc.computeShippingCents([line("a", 500)], 1000)).toBe(300);
    });

    it("selects second bracket (501g–1000g)", () => {
      expect(calc.computeShippingCents([line("a", 501)], 1000)).toBe(500);
    });

    it("selects third bracket (1001g–5000g)", () => {
      expect(calc.computeShippingCents([line("a", 2500, 2)], 1000)).toBe(1000);
    });

    it("uses heaviest bracket cost as overflow default", () => {
      expect(calc.computeShippingCents([line("a", 6000)], 1000)).toBe(1000);
    });

    it("uses explicit overflowCostCents when provided", () => {
      const withOverflow = new WeightBasedShippingCalculator(brackets, 2000);
      expect(
        withOverflow.computeShippingCents([line("a", 6000)], 1000),
      ).toBe(2000);
    });

    it("sorts brackets regardless of input order", () => {
      const unsorted: WeightBracket[] = [
        { upToGrams: 5000, costCents: 1000 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ];
      const calc2 = new WeightBasedShippingCalculator(unsorted);
      expect(calc2.computeShippingCents([line("a", 250)], 1000)).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      const lines = [line("a", 400, 1), line("b", 200, 2)];
      // 400 + 200*2 = 800 → second bracket (500–1000)
      expect(calc.computeShippingCents(lines, 1000)).toBe(500);
    });
  });
});

