+    const calc = new WeightBasedShippingCalculator(brackets);
+
+    it("returns 0 for empty cart", () => {
+      expect(calc.computeShippingCents([], 0)).toBe(0);
+    });
+
+    it("returns 0 when all items have zero/undefined weight", () => {
+      expect(
+        calc.computeShippingCents([noWeightLine("a", 3)], 1000),
+      ).toBe(0);
+    });
+
+    it("selects first bracket (weight ≤ 500g)", () => {
+      expect(calc.computeShippingCents([line("a", 250, 2)], 1000)).toBe(300);
+    });
+
+    it("selects bracket at exact boundary (500g)", () => {
+      expect(calc.computeShippingCents([line("a", 500)], 1000)).toBe(300);
+    });
+
+    it("selects second bracket (501g–1000g)", () => {
+      expect(calc.computeShippingCents([line("a", 501)], 1000)).toBe(500);
+    });
+
+    it("selects third bracket (1001g–5000g)", () => {
+      expect(calc.computeShippingCents([line("a", 2500, 2)], 1000)).toBe(1000);
+    });
+
+    it("uses heaviest bracket cost as overflow default", () => {
+      expect(calc.computeShippingCents([line("a", 6000)], 1000)).toBe(1000);
+    });
+
+    it("uses explicit overflowCostCents when provided", () => {
+      const withOverflow = new WeightBasedShippingCalculator(brackets, 2000);
+      expect(
+        withOverflow.computeShippingCents([line("a", 6000)], 1000),
+      ).toBe(2000);
+    });
+
+    it("sorts brackets regardless of input order", () => {
+      const unsorted: WeightBracket[] = [
+        { upToGrams: 5000, costCents: 1000 },
+        { upToGrams: 500, costCents: 300 },
+        { upToGrams: 1000, costCents: 500 },
+      ];
+      const calc2 = new WeightBasedShippingCalculator(unsorted);
+      expect(calc2.computeShippingCents([line("a", 250)], 1000)).toBe(300);
+    });
+
+    it("sums weight across multiple lines", () => {
+      const lines = [line("a", 400, 1), line("b", 200, 2)];
+      // 400 + 200*2 = 800 → second bracket (500–1000)
+      expect(calc.computeShippingCents(lines, 1000)).toBe(500);
+    });
+  });
+});
