import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

describe("Cart – line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts with zero items", () => {
    expect(cart.itemCount).toBe(0);
  });

  it("adds a product", () => {
    cart.add(product(), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("merges quantities when adding the same product twice", () => {
    cart.add(product(), 2);
    cart.add(product(), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("keeps distinct products separate", () => {
    cart.add(product({ id: "a" }), 1);
    cart.add(product({ id: "b" }), 2);
    expect(cart.itemCount).toBe(3);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(2);
  });

  it("rejects non-positive quantity on add", () => {
    expect(() => cart.add(product(), 0)).toThrow(RangeError);
    expect(() => cart.add(product(), -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on add", () => {
    expect(() => cart.add(product(), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents", () => {
    expect(() => cart.add(product({ unitPriceCents: -1 }), 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    cart.add(product(), 1);
    expect(cart.remove("p1")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updates quantity of existing product", () => {
    cart.add(product(), 3);
    cart.updateQuantity("p1", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("removes product when updating quantity to 0", () => {
    cart.add(product(), 3);
    cart.updateQuantity("p1", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("throws when updating quantity of absent product", () => {
    expect(() => cart.updateQuantity("missing", 5)).toThrow("not in the cart");
  });

  it("rejects negative quantity on updateQuantity", () => {
    cart.add(product(), 1);
    expect(() => cart.updateQuantity("p1", -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on updateQuantity", () => {
    cart.add(product(), 1);
    expect(() => cart.updateQuantity("p1", 2.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    cart.add(product({ id: "a" }), 1);
    cart.add(product({ id: "b" }), 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns deep copies", () => {
    cart.add(product(), 2);
    const snap = cart.snapshot();
    snap[0]!.quantity = 99;
    snap[0]!.product.unitPriceCents = 0;
    // Internal state unchanged
    expect(cart.itemCount).toBe(2);
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(1000);
  });
});

describe("Cart – totals (pricing pipeline)", () => {
  it("computes subtotal as sum of unitPrice × quantity", () => {
    const cart = new Cart();
    cart.add(product({ id: "a", unitPriceCents: 500 }), 2);
    cart.add(product({ id: "b", unitPriceCents: 300 }), 3);
    const totals = cart.totals();
    // 500*2 + 300*3 = 1900
    expect(totals.subtotalCents).toBe(1900);
  });

  it("applies discount, then tax on discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({ discountPolicy, taxCalculator });
    cart.add(product({ unitPriceCents: 1000 }), 1);
    const totals = cart.totals();

    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(200);
    // Tax computed on discounted subtotal (1000 - 200 = 800)
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US");
    expect(totals.taxCents).toBe(80);
  });

  it("shipping receives discounted subtotal and lines", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(product({ unitPriceCents: 500 }), 2);
    const totals = cart.totals();

    // Discounted subtotal = 1000 - 100 = 900
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      900,
    );
    expect(totals.shippingCents).toBe(599);
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 200,
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: () => 80,
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => 500,
    };
    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
    cart.add(product({ unitPriceCents: 1000 }), 1);
    const totals = cart.totals();

    expect(totals.totalCents).toBe(800 + 80 + 500); // 1380
  });

  it("clamps discount to [0, subtotal] — negative discount becomes 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => -100,
    };
    const cart = new Cart({ discountPolicy });
    cart.add(product({ unitPriceCents: 500 }), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.totalCents).toBe(500);
  });

  it("clamps discount to [0, subtotal] — over-subtotal discount capped", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 9999,
    };
    const cart = new Cart({ discountPolicy });
    cart.add(product({ unitPriceCents: 500 }), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(500);
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: () => -50,
    };
    const cart = new Cart({ taxCalculator });
    cart.add(product({ unitPriceCents: 500 }), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => -10,
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(product({ unitPriceCents: 500 }), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("empty cart yields all zeros", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("uses default collaborators (no discount, no tax, free shipping)", () => {
    const cart = new Cart();
    cart.add(product({ unitPriceCents: 1000 }), 2);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(2000);
  });

  it("uses custom region for tax", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator, region: "FR" });
    cart.add(product(), 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(
      expect.any(Number),
      "FR",
    );
  });
});

describe("Cart – checkout()", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(product(), 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(product({ id: "a", unitPriceCents: 100 }), 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(500),
    };
    const result = await cart.checkout({ priceFetcher });
    // After price refresh: 500 * 2 = 1000
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines[0]!.product.unitPriceCents).toBe(500);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(product({ id: "sold-out" }), 3);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "out of stock" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("sold-out");
      expect(invErr.requested).toBe(3);
      expect(invErr.message).toBe("out of stock");
    }
  });

  it("throws InventoryError for partial-stock denial (availableQuantity < requested)", async () => {
    const cart = new Cart();
    cart.add(product({ id: "limited" }), 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("limited");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("succeeds when inventory is available", async () => {
